<script lang="ts">
 import {enhance} from '$app/forms';import Aviso from '#lib/componentes/Aviso.svelte';import LinkConvite from '#lib/componentes/LinkConvite.svelte';import {nomeNaEscala,nomeNaSaudacao,STATUS_OBREIRO,ehPb,resumoDisponibilidade} from '#lib/util';
 let {data,form}=$props();let busca=$state(''),convidando=$state(false);
 const grupo=(u:typeof data.obreiros[number])=>['coordenador','vice'].includes(u.perfil)?0:u.perfil==='pb'?1:u.cargo==='Diácono'?2:u.cargo==='Auxiliar Oficial'?3:u.cargo==='Auxiliar Local'?4:5;
 const grupos=$derived(['Coordenação da Área','Responsáveis por Congregação','Diáconos','Auxiliares Oficiais','Auxiliares Locais','Demais obreiros'].map((titulo,i)=>({titulo,pessoas:data.obreiros.filter(u=>grupo(u)===i&&(!busca||`${u.nome} ${u.carteira}`.toLocaleLowerCase('pt-BR').includes(busca.toLocaleLowerCase('pt-BR')))).sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'))})).filter(g=>g.pessoas.length));
</script>
<h1 class="titulo">Obreiros e convites</h1><Aviso {form}/>
<button type="button" class="btn btn-primario mt-4" aria-expanded={convidando} aria-controls="convite-obreiro" onclick={()=>convidando=!convidando}>Convidar Obreiro</button>{#if convidando}<section id="convite-obreiro" class="cartao mt-3"><p class="mt-3 text-sm text-gray-600">O convite fica vinculado à congregação selecionada.</p><form method="POST" action="?/criarConvite" use:enhance class="flex flex-wrap gap-2 mt-3"><input type="hidden" name="perfil" value="obreiro"/>{#if ehPb(data.user)}<input type="hidden" name="congregacao_id" value={data.user!.congregacao_id}/><p class="text-sm self-center">{data.user!.congregacao}</p>{:else}<select class="campo w-full sm:flex-1" name="congregacao_id" aria-label="Congregação do obreiro" required><option value="">Selecione a congregação</option>{#each data.congregacoes as c (c.id)}<option value={c.id}>{c.nome}</option>{/each}</select>{/if}<button class="btn btn-primario">Gerar convite</button></form></section>{/if}
{#if form&&'link' in form&&form.link}<LinkConvite link={form.link}/>{/if}
<input class="campo mt-5" type="search" bind:value={busca} aria-label="Buscar obreiro" placeholder="Buscar por nome ou carteira"/>
{#each grupos as g (g.titulo)}<section class="mt-5"><h2 class="font-semibold mb-3">{g.titulo}</h2><div class="grid gap-3 md:grid-cols-2">{#each g.pessoas as u (u.id)}<a class="cartao" href="/obreiros/{u.id}"><div class="flex flex-wrap justify-between gap-2"><strong class="text-sm">{['coordenador','vice'].includes(u.perfil)?nomeNaSaudacao({...u,perfil:u.perfil as 'coordenador'|'vice'}):nomeNaEscala(u)}</strong><span class="selo {STATUS_OBREIRO[u.status].cor}">{STATUS_OBREIRO[u.status].rotulo}</span></div><p class="text-xs text-gray-500 mt-2">{u.congregacao} · Carteira {u.carteira}</p><p class="text-xs text-gray-600 mt-2">{resumoDisponibilidade(u.disponibilidade)}</p></a>{/each}</div></section>{:else}<p class="cartao mt-4 text-sm">Nenhum obreiro encontrado.</p>{/each}
